package glitch

import data.glitch_lib

# Helper to check if a string value represents an insecure protocol
is_insecure_protocol(value) {
    value.ir_type == "String"
    regex.match("(?i)^http://", value.value)
}

# Helper to check if a value indicates a security check is disabled
is_security_disabled(value) {
    value.ir_type == "String"
    regex.match("(?i)^(no|false|disabled|0)$", value.value)
}

is_security_disabled(value) {
    value.ir_type == "Boolean"
    value.value == false
}

is_security_disabled(value) {
    value.ir_type == "Integer"
    value.value == 0
}

# Rule 1: Detect insecure protocols in URL attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    attr_name := lower(attr.name)
    url_attrs := {"url", "source", "baseurl"}
    url_attrs[_] == attr_name

    is_insecure_protocol(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Using plaintext protocol (CWE-353)"
    }
}

# Rule 2: Detect disabled security/validation attributes
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    attrs := glitch_lib.all_attributes(parent)
    attr := attrs[_]

    attr_name := lower(attr.name)
    security_attrs := {"validate_certs", "gpgcheck", "ssl", "tls_version"}
    security_attrs[_] == attr_name

    is_security_disabled(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Security validation is disabled (CWE-353)"
    }
}

# Rule 3: Detect insecure protocols in atomic units (Ansible/Cheb resources)
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr_name := lower(attr.name)
    url_attrs := {"url", "source", "baseurl"}
    url_attrs[_] == attr_name

    is_insecure_protocol(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Using plaintext protocol (CWE-353)"
    }
}

# Rule 4: Detect disabled security checks in atomic units
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    attr_name := lower(attr.name)
    security_attrs := {"validate_certs", "gpgcheck", "ssl", "warn"}
    security_attrs[_] == attr_name

    is_security_disabled(attr.value)

    result := {
        "type": "sec_no_int_check",
        "element": attr,
        "path": parent.path,
        "description": "Missing Support for Integrity Check - Security validation is disabled (CWE-353)"
    }
}

